interface ItemDoPedido {
  preco: number
  quantidade: number
}

function resumirPedido(itens: ItemDoPedido[], cupom: number | null) {
  const subtotal = itens.reduce((soma, item) => soma + item.preco * item.quantidade, 0)

  // O tipo `number | null` obriga a tratar a ausencia aqui, e nao depois.
  const desconto = cupom === null ? 0 : Math.min(cupom, subtotal)

  return { subtotal, desconto, total: subtotal - desconto }
}

