function calcularModo(selecionados, total) {
  if (selecionados.length === 0) return 'nenhum'
  return selecionados.length >= total ? 'todos' : 'alguns'
}

function reduzir(estado, acao) {
  switch (acao.tipo) {
    case 'alternar': {
      const jaEstava = estado.selecionados.includes(acao.id)
      const selecionados = jaEstava
        ? estado.selecionados.filter((id) => id !== acao.id)
        : [...estado.selecionados, acao.id]
      return { selecionados, modo: calcularModo(selecionados, acao.total) }
    }

    case 'limpar':
      return { selecionados: [], modo: 'nenhum' }

    case 'selecionarTodos':
      return { selecionados: [...acao.ids], modo: calcularModo(acao.ids, acao.ids.length) }

    default:
      // Acao desconhecida nao gera estado novo: evita redesenho a toa.
      return estado
  }
}

