function criarBuscador() {
  // Simbolo proprio: '' e um termo valido e nao pode ser o estado inicial.
  const NENHUM = Symbol('nenhum')
  let atual = NENHUM

  return {
    aceitar(termo) {
      atual = termo
    },
    registrar(termo, resultado) {
      return termo === atual ? resultado : null
    },
  }
}

