'use client'

export function FiltroDeStatus({ inicial, podeVerTodos }: { inicial: string; podeVerTodos: boolean }) {
  const [status, setStatus] = useState(inicial)

  return (
    <select value={status} onChange={(evento) => setStatus(evento.target.value)}>
      <option value="meus">Meus tickets</option>
      {podeVerTodos ? <option value="todos">Todos</option> : null}
    </select>
  )
}

