interface Filtros {
  status?: string
  busca?: string
  pagina?: number
}

function montarQuery(filtros: Filtros): string {
  return Object.entries(filtros)
    // Vazio é undefined ou texto em branco. Zero é um valor, e entra.
    .filter(([, valor]) => valor !== undefined && valor !== '')
    .map(([chave, valor]) => `${chave}=${encodeURIComponent(String(valor))}`)
    .join('&')
}
